namespace RonSijm.FluidHumidifier.Factories.BedrockAgentCore;

public class OnlineEvaluationConfigFactory(string resourceName = null, Action<Humidifier.BedrockAgentCore.OnlineEvaluationConfig> factoryAction = null) : ResourceFactory<Humidifier.BedrockAgentCore.OnlineEvaluationConfig>(resourceName)
{

    internal List<InnerOnlineEvaluationConfigInsightFactory> InsightsFactories { get; set; } = [];

    internal List<InnerOnlineEvaluationConfigEvaluatorReferenceFactory> EvaluatorsFactories { get; set; } = [];

    internal InnerOnlineEvaluationConfigOutputConfigFactory OutputConfigFactory { get; set; }

    internal InnerOnlineEvaluationConfigDataSourceConfigFactory DataSourceConfigFactory { get; set; }

    internal InnerOnlineEvaluationConfigClusteringConfigFactory ClusteringConfigFactory { get; set; }

    internal InnerOnlineEvaluationConfigRuleFactory RuleFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.OnlineEvaluationConfig Create()
    {
        var onlineEvaluationConfigResult = CreateOnlineEvaluationConfig();
        factoryAction?.Invoke(onlineEvaluationConfigResult);

        return onlineEvaluationConfigResult;
    }

    private Humidifier.BedrockAgentCore.OnlineEvaluationConfig CreateOnlineEvaluationConfig()
    {
        var onlineEvaluationConfigResult = new Humidifier.BedrockAgentCore.OnlineEvaluationConfig
        {
            GivenName = InputResourceName,
        };

        return onlineEvaluationConfigResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.OnlineEvaluationConfig result)
    {
        base.CreateChildren(result);

        result.Insights = InsightsFactories.Any() ? InsightsFactories.Select(x => x.Build()).ToList() : null;
        result.Evaluators = EvaluatorsFactories.Any() ? EvaluatorsFactories.Select(x => x.Build()).ToList() : null;
        result.OutputConfig ??= OutputConfigFactory?.Build();
        result.DataSourceConfig ??= DataSourceConfigFactory?.Build();
        result.ClusteringConfig ??= ClusteringConfigFactory?.Build();
        result.Rule ??= RuleFactory?.Build();
    }

} // End Of Class

